// Entry point for Cloudflare Workers: the OpenNext handler plus a scheduled
// handler for the cron jobs (reminder e-mails, demo account reset).
// Generated by `opennextjs-cloudflare build`; may not exist yet when type-checking a fresh clone.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";

// Minimal Workers runtime shapes, so the full runtime typings don't clash with DOM types in the app.
interface Env {
  CRON_SECRET?: string;
  NEXT_PUBLIC_SITE_URL?: string;
}
interface WorkerContext {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
}
interface WorkerHandler {
  fetch(request: Request, env: Env, ctx: WorkerContext): Promise<Response>;
}

const worker = handler as WorkerHandler;

/** Must match triggers.crons in wrangler.jsonc. */
const CRON_ROUTES: Record<string, string> = {
  "0 15 * * *": "/api/cron/reminders",
  "30 * * * *": "/api/cron/demo-reset",
};

const entry = {
  fetch: worker.fetch,

  async scheduled(controller: { cron: string }, env: Env, ctx: WorkerContext): Promise<void> {
    const path = CRON_ROUTES[controller.cron];
    if (!path) {
      console.error(`[cron] no route for schedule "${controller.cron}"`);
      return;
    }
    if (!env.CRON_SECRET) {
      console.error(`[cron] CRON_SECRET is not set, skipping ${path}`);
      return;
    }
    const origin = env.NEXT_PUBLIC_SITE_URL ?? "https://rezervo.internal";
    const request = new Request(new URL(path, origin), {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    const response = await worker.fetch(request, env, ctx);
    const body = await response.text();
    if (!response.ok) throw new Error(`[cron] ${path} failed with HTTP ${response.status}: ${body}`);
    console.info(`[cron] ${path}`, body);
  },
};

export default entry;
